{"point":{"id":"persistence","title":"Durable Records and Publication","rationale":"Persistence distinguishes the editable workspace from published catalog representations. WorkspaceRecordStore writes content-addressed records before atomically replacing a manifest containing revision guards and retry receipts. Catalog publication can pin an already persisted checkpoint without expanding its entire archive. DiagramStore supplies the shared repository facade.","sourcePaths":["infrastructure/core/persistence/store.ts","infrastructure/core/persistence/canvasCatalogStore.ts","infrastructure/core/persistence/projectCatalogStore.ts","infrastructure/core/persistence/diagramRevisionStore.ts","infrastructure/mapping/persistence/workspace/workspaceRecordStore.ts","domain/mapping/workspace/workspaceRecords.ts","domain/core/diagrams/canvasCheckpointRecords.ts","application/mapping/workspace/workspaceService.ts","application/mapping/diagrams/diagramService.ts"],"relationships":[{"pointId":"canvas_commands","label":"persists checkpoint graphs, composition, and view records","kind":"dependency"},{"pointId":"diagrams","label":"stores immutable revisions before publishing references","kind":"dependency"}]},"sources":[{"path":"infrastructure/core/persistence/store.ts","text":"import { GitRepositoryRegistry } from './repositoryRegistry';
import { DiagramPersistence } from '../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from './diagramRevisionStore';
import path from "node:path";
import type { RepositoryLocation } from "../../../application/core/corpus/location";
import {
  type ProjectRecord
} from "../../../domain/core/records/domain";
import type { PersistenceContext } from './context';
import { ProjectCatalogStore } from "./projectCatalogStore";
import * as projectsStore from './projects';
export type { RepositoryLocation } from '../../../application/core/corpus/location';
export { discoverDocumentCorpus, discoverDomainCorpus, discoverRepository, projectIdFor } from './shared';

/** Filesystem repository facade; storage operations are grouped by capability. */
export class DiagramStore {
  readonly repositories: GitRepositoryRegistry;
  readonly checkoutRoot: string;
  readonly storeRoot: string;
  readonly projectCatalogs: ProjectCatalogStore;
  readonly diagramPersistence: DiagramPersistence;
  readonly canvases: ProjectCatalogStore;
  private readonly context: PersistenceContext;
  constructor(checkoutRoot: string, diagramsDirectory = ".diagrams") {
    this.checkoutRoot = path.resolve(checkoutRoot);
    this.storeRoot = path.resolve(this.checkoutRoot, diagramsDirectory);
    this.repositories = new GitRepositoryRegistry(this.storeRoot, this.checkoutRoot);
    this.diagramPersistence = new DiagramPersistence(new DiagramRevisionStore(this.storeRoot));
    this.canvases = new ProjectCatalogStore(this.storeRoot, this.diagramPersistence);
    this.projectCatalogs = this.canvases;
    this.context = { checkoutRoot: this.checkoutRoot, storeRoot: this.storeRoot, projectCatalogs: this.projectCatalogs };
  }
  async ensureProject(location: RepositoryLocation): Promise<ProjectRecord> { await projectsStore.ensureProject(this.context, location); return this.repositories.initialize(); }

  async loadProject(): Promise<ProjectRecord | null> { const project = await projectsStore.loadProject(this.context); return project ? this.repositories.initialize() : null; }
}
"},{"path":"infrastructure/core/persistence/canvasCatalogStore.ts","text":"import { canvasTypeOf } from '../../../domain/core/diagrams/canvasType';
import { documentFromHistory } from '../../../domain/core/diagrams/canvasHistory';
import { checkpointPublicationSchema, type CheckpointPublication, type CheckpointReceipt, type CapturedCheckpoint } from '../../../domain/core/diagrams/checkpointPublication';
import { inferRepositoryId } from '../../../domain/core/repositories/repository';
import type { ProjectRecord } from '../../../domain/core/records/domain';
import { DefaultCanvasHistoryService } from '../../../domain/core/diagrams/canvasHistoryService';
import { assertDiagramStorageFormat } from './diagramStorageFormat';
import path from 'node:path';
import { stat } from 'node:fs/promises';
import type { DiagramSourceBinding } from '../../../domain/core/diagrams/diagram';
import type { AcceptCanvasChangesInput, ChangeSessionAcceptance } from '../../../domain/core/representations/changeAcceptance';
import { documentFromRevision, historyFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { ProjectProjectionRecord } from '../../../domain/core/diagrams/diagramProjection';
import type { SaveProjectDiagramInput } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { SaveProjectedTreeInput } from '../../../domain/core/representations/catalogCommands';
import type { ProjectRepresentationCatalogRecord } from '../../../domain/core/representations/projectCatalog';
import * as rules from '../../../domain/core/representations/catalogRules';
import { DiagramPersistence } from '../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from './diagramRevisionStore';
import { readJsonIfExists, writeJsonAtomic, emptyRepresentationCatalog, catalogEnvironment } from './catalogPersistence';

/** Canvas catalog owns composition/publication. DiagramService owns diagram persistence. */
export class CanvasCatalogStore {
  private readonly historyService = new DefaultCanvasHistoryService();
  constructor(readonly storeRoot: string,
    protected readonly diagramPersistence: DiagramPersistence = new DiagramPersistence(new DiagramRevisionStore(storeRoot))) {}

  private representationWrite: Promise<unknown> = Promise.resolve();
  private sourceBindingsCache?: { key: string; value: Promise<DiagramSourceBinding[]> };
  private serialize<T>(write: () => Promise<T>): Promise<T> {
    const result = this.representationWrite.then(write);
    this.representationWrite = result.catch(() => undefined);
    return result;
  }

  saveProjection(projectId: string, projection: ProjectProjectionRecord) {
    return this.serialize(async () => {
      const catalog = await this.readRepresentationCatalog(projectId);
      const result = rules.saveProjection(catalog, projectId, projection, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  /** Persist the generated tree and its relationship in one catalog write. */
  saveProjectedTree(projectId: string, input: SaveProjectedTreeInput) {
    return this.serialize(async () => {
      const catalog = await this.readRepresentationCatalog(projectId);
      const result = rules.saveProjectedTree(catalog, projectId, input, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  backfillPromotionPlacementLineage(projectId: string, input: { requestId: string; signature: string; lineage: import('../../../domain/mapping/evals/placementLineage').PlacementLineage }) {
    return this.serialize(async () => {
      const catalog = await this.readStoredCatalog(projectId);
      const promotion = catalog?.outputPromotions?.[input.requestId];
      if (!catalog || !promotion || promotion.signature !== input.signature) throw Error('Promotion request does not match');
      if (promotion.receipt.placementLineage) {
        if (JSON.stringify(promotion.receipt.placementLineage) !== JSON.stringify(input.lineage)) throw Error('Placement lineage is immutable');
        return promotion.receipt;
      }
      promotion.receipt.placementLineage = structuredClone(input.lineage);
      // Metadata-only write: retained canvas/checkpoint references remain byte-for-byte unchanged.
      await writeJsonAtomic(this.representationCatalogPath(), catalog);
      return promotion.receipt;
    });
  }

  publishOutputPromotion(projectId: string, input: import('../../../domain/mapping/evals/outputPromotion').PromotionPublication) {
    return this.serialize(async () => {
      let catalog = await this.readRepresentationCatalog(projectId);
      const prior = catalog.outputPromotions?.[input.requestId];
      if (prior) {
        if (prior.signature !== input.signature) throw Error('REQUEST_ID_CONFLICT');
        return prior.receipt;
      }
      const project = await readJsonIfExists<ProjectRecord>(path.join(this.storeRoot, 'project.json'));
      if (input.canvasProject) catalog = { ...catalog, canvasProjects: { ...catalog.canvasProjects, [input.canvasProject.id]: input.canvasProject } };
      const receipt: import('../../../domain/mapping/evals/outputPromotion').PromotionReceipt = { requestId: input.requestId,
        canvasProjectId: input.canvasProject?.id ?? input.documents[0]?.canvasProjectId, canvases: [] };
      const promotedAt = new Date().toISOString();
      if (input.placementSource) receipt.placementLineage = { schemaVersion: 1, coordinateSpace: 'canvas-grid', source: input.placementSource, promotedAt, diagrams: [] };
      for (const doc of input.documents) {
        if (doc.canvasProjectId && !catalog.canvasProjects?.[doc.canvasProjectId]) throw Error('Canvas project not found');
        if (doc.repositoryId && !project?.repositories?.some(r => r.id === doc.repositoryId)) throw Error('Unknown repositoryId');
        const result = rules.saveMappingDiagram(catalog, projectId, doc, { ...catalogEnvironment(), representationId: doc.id });
        catalog = result.catalog; receipt.canvases.push({ id: result.representation.id, name: result.representation.name });
        if (receipt.placementLineage) {
          if (!doc.placementBindings?.length) throw Error('Promotion placement bindings are required');
          for (const binding of doc.placementBindings) {
            if (binding.promoted.canvasId !== result.representation.id) throw Error('Promotion placement canvas mismatch');
            receipt.placementLineage.diagrams.push({ ...binding, promoted: { ...binding.promoted,
              checkpointId: doc.history.headId, canvasRevisionId: result.representation.currentRevisionId } });
          }
        }
      }
      catalog.outputPromotions = { ...catalog.outputPromotions, [input.requestId]: { signature: input.signature, receipt } };
      // Publish group membership, all remapped canvases and the retry receipt atomically.
      await this.saveRepresentationCatalog(catalog);
      return receipt;
    });
  }

  saveMappingDiagram(projectId: string, input: SaveProjectDiagramInput) {
    return this.serialize(async () => {
      const catalog = await this.readRepresentationCatalog(projectId);
      // Generation publication is retryable, including after a process restart.
      if (input.generated && !input.representationId) {
        const prior = Object.values(catalog.representations).find(item => item.generated?.key === input.generated!.key);
        if (prior) return { catalog, representation: prior };
      }
      const project = await readJsonIfExists<ProjectRecord>(path.join(this.storeRoot, 'project.json'));
      const current = input.representationId ? catalog.representations[input.representationId] : undefined;
      const copied = input.sourceRevisionId ? catalog.representations[catalog.revisions[input.sourceRevisionId]?.representationId]?.repositoryId : undefined;
      const repositoryId = input.repositoryId ?? current?.repositoryId ?? copied ?? (!current ? inferRepositoryId(input.scene, project?.repositories ?? []) : undefined);
      if (repositoryId && !project?.repositories?.some(repo => repo.id === repositoryId)) throw Error('Unknown repositoryId');
      if (!current && project?.repositories?.length && !repositoryId) throw Error('Specify repositoryId for the new canvas');
      const result = rules.saveMappingDiagram(catalog, projectId, { ...input, repositoryId }, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  publishCheckpoint(projectId: string, raw: CheckpointPublication, captureCheckpoint: () => Promise<CapturedCheckpoint>): Promise<CheckpointReceipt> {
    const input = checkpointPublicationSchema.parse(raw);
    return this.serialize(async () => {
      const started = Date.now();
      const catalog = await this.readStoredCatalog(projectId) ?? emptyRepresentationCatalog(projectId);
      const receipts = (catalog as typeof catalog & { checkpointReceipts?: Record<string, { signature: string; receipt: CheckpointReceipt }> }).checkpointReceipts ?? {};
      const signature = JSON.stringify(input), old = receipts[input.requestId];
      if (old) { if (old.signature !== signature) throw Error('REQUEST_ID_CONFLICT'); return old.receipt; }
      const current = input.representationId ? catalog.representations[input.representationId] : undefined;
      if (input.representationId && (!current || current.status !== 'settled' || current.currentRevisionId !== input.expectedRevisionId))
        throw Error('VERSION_CONFLICT: published canvas changed; reread before saving');
      if (current?.repositoryId && input.repositoryId && current.repositoryId !== input.repositoryId) throw Error('Canvas repository ownership cannot change on save');
      const capture = await captureCheckpoint();
      const history = { ...capture.header, baselineId: input.checkpointId, headId: input.checkpointId, past: [], future: [],
        snapshots: { [input.checkpointId]: { ...capture.head, parentId: undefined } }, diagramRevisions: capture.revisions };
      const document = documentFromHistory(history);
      const project = await readJsonIfExists<ProjectRecord>(path.join(this.storeRoot, 'project.json'));
      const repositoryId = input.repositoryId ?? current?.repositoryId ?? capture.metadata.repositoryId ?? inferRepositoryId(document.scene, project?.repositories ?? []);
      if (repositoryId && !project?.repositories?.some(repo => repo.id === repositoryId)) throw Error('Unknown repositoryId');
      if (!current && project?.repositories?.length && !repositoryId) throw Error('Specify repositoryId for the new canvas');
      const result = rules.publishMappingDiagram(catalog, projectId, { ...input, type: capture.metadata.type, repositoryId, history, scene: document.scene, edges: document.edges }, catalogEnvironment());
      const revisionId = result.representation.currentRevisionId;
      // Publish immutable references already committed by autosave; never hydrate old catalog revisions.
      result.catalog.revisions[revisionId].content = { kind: 'canvas-history', history: capture.stored as import('../../../domain/core/diagrams/canvasHistory').CanvasHistoryRecord };
      const receipt = { representation: result.representation, revisionId, savedVersion: input.expectedVersion, checkpointId: input.checkpointId };
      await writeJsonAtomic(this.representationCatalogPath(), { ...result.catalog, checkpointReceipts: { ...receipts, [input.requestId]: { signature, receipt } } });
      console.debug('canvas-publish', { durationMs: Date.now() - started, receiptBytes: Buffer.byteLength(JSON.stringify(receipt)) });
      return receipt;
    });
  }

  acceptCanvasChanges(projectId: string, input: AcceptCanvasChangesInput): Promise<ChangeSessionAcceptance> {
    return this.serialize(async () => {
      let catalog = await this.readRepresentationCatalog(projectId);
      const prior = catalog.changeSessionAcceptances?.[input.changeSessionId];
      if (prior) {
        if (prior.requestId !== input.requestId || prior.sessionVersion !== input.sessionVersion)
          throw new Error('REQUEST_ID_CONFLICT: proposal already accepted');
        return prior;
      }
      if (!input.documents.length || new Set(input.documents.map(d => d.documentId)).size !== input.documents.length)
        throw new Error('Acceptance requires distinct changed documents');
      const targets = input.documents.flatMap(d => d.representationId ? [d.representationId] : []);
      if (new Set(targets).size !== targets.length) throw new Error('Duplicate acceptance target');
      const acceptance: ChangeSessionAcceptance = { changeSessionId: input.changeSessionId, sessionVersion: input.sessionVersion,
        requestId: input.requestId, acceptedAt: new Date().toISOString(), changeIds: [...input.changeIds], documents: [] };
      for (const doc of input.documents) {
        const project = await readJsonIfExists<ProjectRecord>(path.join(this.storeRoot, 'project.json'));
        if (doc.repositoryId && !project?.repositories?.some(repo => repo.id === doc.repositoryId)) throw Error('Unknown repositoryId');
        const current = doc.representationId ? catalog.representations[doc.representationId] : undefined;
        if (doc.representationId && (!current || current.status !== 'settled' || current.currentRevisionId !== doc.expectedRevisionId))
          throw new Error('VERSION_CONFLICT: original canvas changed; create a new proposal');
        const proposed = this.historyService.openContext(doc.document, doc.history.snapshots[doc.history.headId].view, doc.history);
        let history = this.historyService.forkContext(proposed, doc.history.snapshots[doc.history.headId].view);
        let before: ChangeSessionAcceptance['documents'][number]['before'] = null;
        if (current) {
          const revision = catalog.revisions[current.currentRevisionId], saved = historyFromRevision(revision);
          const context = this.historyService.openContext(documentFromRevision(revision), saved?.snapshots[saved.headId].view ?? {}, saved);
          before = { revisionId: revision.id, checkpointId: this.historyService.state(context).checkpointId };
          this.historyService.adopt(context, doc.history);
          history = this.historyService.exportContext(context);
        }
        const result = rules.saveMappingDiagram(catalog, projectId, { name: doc.name, repositoryId: doc.repositoryId, representationId: doc.representationId,
          expectedRevisionId: doc.expectedRevisionId, scene: doc.document.scene, edges: doc.document.edges, history }, catalogEnvironment());
        catalog = result.catalog;
        acceptance.documents.push({ documentId: doc.documentId, representationId: result.representation.id, before,
          after: { revisionId: result.representation.currentRevisionId, checkpointId: history.headId }, proposedCheckpointId: doc.history.headId });
      }
      catalog = { ...catalog, changeSessionAcceptances: { ...catalog.changeSessionAcceptances, [input.changeSessionId]: acceptance } };
      // A failure before this write publishes none of the canvases. The receipt and
      // all new heads become visible in the same atomic catalog replacement.
      await this.saveRepresentationCatalog(catalog);
      return acceptance;
    });
  }

  private representationCatalogPath(): string {
    return path.join(this.storeRoot, 'canvases', 'catalog.json');
  }

  private async readStoredCatalog(projectId: string) {
    const raw = await readJsonIfExists<ProjectRepresentationCatalogRecord>(this.representationCatalogPath())
      ?? await readJsonIfExists<ProjectRepresentationCatalogRecord>(path.join(this.storeRoot, 'representations', 'catalog.json'));
    if (raw && raw.projectId !== projectId) throw new Error('representation catalog belongs to another Project');
    return raw;
  }

  /** Publication receipts contain no diagram references; listing proposals needs no restored catalog. */
  async loadChangeSessionAcceptances(projectId: string) {
    return (await this.readStoredCatalog(projectId))?.changeSessionAcceptances ?? {};
  }

  /** Coalesce file reads and invalidate on atomic catalog replacement, including external saves. */
  async loadDiagramSourceBindings(projectId: string): Promise<DiagramSourceBinding[]> {
    const metadata = async (file: string) => {
      try { const info = await stat(file); return `${file}:${info.ino}:${info.size}:${info.mtimeMs}:${info.ctimeMs}`; }
      catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined; throw error; }
    };
    const key = `${projectId}:${await metadata(this.representationCatalogPath())
      ?? await metadata(path.join(this.storeRoot, 'representations', 'catalog.json')) ?? 'empty'}`;
    if (this.sourceBindingsCache?.key !== key) {
      const value = (async () => {
        await assertDiagramStorageFormat(this.storeRoot);
        const catalog = await this.readStoredCatalog(projectId);
        return this.diagramPersistence.sourceBindings(Object.values(catalog?.revisions ?? {}).map(revision => {
          if (revision.content?.kind !== 'canvas-history') throw new Error('Unsupported legacy diagram content: canvas history is required');
          return revision.content.history;
        }));
      })();
      const entry = { key, value };
      this.sourceBindingsCache = entry;
      void value.catch(() => { if (this.sourceBindingsCache === entry) this.sourceBindingsCache = undefined; });
    }
    return structuredClone(await this.sourceBindingsCache.value);
  }

  loadCurrentRepresentationCatalog(projectId: string, revisionIds?: string[]): Promise<ProjectRepresentationCatalogRecord> {
    return this.serialize(async () => {
      const catalog = await this.readStoredCatalog(projectId) ?? emptyRepresentationCatalog(projectId);
      const ids = revisionIds ?? Object.values(catalog.representations).map(rep => rep.currentRevisionId);
      const revisions = Object.fromEntries(await Promise.all([...new Set(ids)].map(async id => {
        const revision = catalog.revisions[id];
        if (!revision || revision.content?.kind !== 'canvas-history') throw Error('Unknown canvas revision');
        return [id, { ...revision, content: { kind: 'canvas-history', history: await this.diagramPersistence.currentHistory(revision.content.history) } }];
      })));
      const result: ProjectRepresentationCatalogRecord = { ...catalog, revisions };
      this.normalizeCanvasTypes(result);
      return result;
    });
  }

  loadRepresentationCatalog(projectId: string, historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all'): Promise<ProjectRepresentationCatalogRecord> {
    return this.serialize(() => this.readRepresentationCatalog(projectId, historyValidation));
  }

  private async readRepresentationCatalog(projectId: string, historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all'): Promise<ProjectRepresentationCatalogRecord> {
    await assertDiagramStorageFormat(this.storeRoot);
    const raw = await this.readStoredCatalog(projectId);
    const stored = raw == null ? null : await this.diagramPersistence.restore<ProjectRepresentationCatalogRecord>(raw, historyValidation);
    if (!stored) return emptyRepresentationCatalog(projectId);
    if (stored.projectId !== projectId) {
      throw new Error("representation catalog belongs to another Project");
    }
    for (const revision of Object.values(stored.revisions)) if (revision.content?.kind !== 'canvas-history')
      throw new Error('Unsupported legacy diagram content: canvas history is required');
    this.normalizeCanvasTypes(stored);
    if (!stored.repositoryOwnershipVersion && Object.keys(stored.representations).length) {
      const project = await readJsonIfExists<ProjectRecord>(path.join(this.storeRoot, 'project.json'));
      if (project?.repositories?.length) {
        for (const representation of Object.values(stored.representations)) {
          const revision = stored.revisions[representation.currentRevisionId];
          if (!representation.repositoryId && revision) representation.repositoryId = inferRepositoryId(documentFromRevision(revision).scene, project.repositories);
        }
        stored.repositoryOwnershipVersion = 1;
        await this.saveRepresentationCatalog(stored);
      }
    }
    return stored;
  }

  /** Infer legacy catalog types from already restored heads; never load extra history. */
  private normalizeCanvasTypes(catalog: ProjectRepresentationCatalogRecord) {
    for (const representation of Object.values(catalog.representations)) {
      const revision = catalog.revisions[representation.currentRevisionId];
      if (!revision && representation.type === undefined) continue;
      const history = revision?.content?.kind === 'canvas-history' ? revision.content.history : undefined;
      representation.type = canvasTypeOf({ type: representation.type,
        canvas: history?.snapshots[history.headId]?.view as { projectionLayout?: unknown } | undefined });
    }
  }

  async saveRepresentationCatalog(catalog: ProjectRepresentationCatalogRecord): Promise<void> {
    await writeJsonAtomic(this.representationCatalogPath(), await this.diagramPersistence.persist(catalog));
  }

  archiveRepresentation(projectId: string, representationId: string, options?: { includeHistory?: boolean }) {
    return this.serialize(() => this.archiveRepresentationUnlocked(projectId, representationId, options?.includeHistory !== false));
  }

  private async archiveRepresentationUnlocked(
    projectId: string,
    representationId: string,
    includeHistory: boolean
  ): Promise<ProjectRepresentationCatalogRecord> {
    // Archiving only changes catalog metadata. Keep immutable history references encoded.
    const catalog = await this.readStoredCatalog(projectId) ?? emptyRepresentationCatalog(projectId);
    const result = rules.archiveRepresentation(catalog, projectId, representationId, catalogEnvironment());
    if (result !== catalog) await writeJsonAtomic(this.representationCatalogPath(), result);
    return includeHistory ? this.readRepresentationCatalog(projectId) : { ...result, revisions: {} };
  }
}
